BEGIN ISOLATION LEVEL SERIALIZABLE;
for attempt in 1..3:
  try:
    UPDATE ...;      -- fails with 40001
  except SerializationFailure:
    continue;        -- retry only this statement
COMMIT;

-- both transactions, concurrently:
BEGIN ISOLATION LEVEL <level>;
SELECT count(*) FROM doctor WHERE on_call = true;   -- both read 2
UPDATE doctor SET on_call = false WHERE id = :self;  -- different rows
COMMIT;

